const glow=document.getElementById('cursor-glow');window.addEventListener('mousemove',e=>{glow.style.setProperty('--mouse-x',`${e.clientX}px`);glow.style.setProperty('--mouse-y',`${e.clientY}px`);glow.classList.remove('opacity-0')});window.addEventListener('mouseout',()=>glow.classList.add('opacity-0'));const mobileMenuBtn=document.getElementById('mobile-menu-btn'),mobileMenuClose=document.getElementById('mobile-menu-close'),mobileMenu=document.getElementById('mobile-menu'),mobileLinks=mobileMenu.querySelectorAll('a');mobileMenuBtn?.addEventListener('click',()=>mobileMenu.classList.remove('translate-x-full'));mobileMenuClose?.addEventListener('click',()=>mobileMenu.classList.add('translate-x-full'));mobileLinks.forEach(link=>{link.addEventListener('click',()=>mobileMenu.classList.add('translate-x-full'))});document.querySelectorAll('a[href^="#"]').forEach(anchor=>{anchor.addEventListener('click',function(e){const targetId=this.getAttribute('href');if(targetId==='#')return;const targetElement=document.querySelector(targetId);if(targetElement){e.preventDefault();const targetPosition=targetElement.getBoundingClientRect().top+window.pageYOffset,startPosition=window.pageYOffset,distance=targetPosition-startPosition,duration=600;let start=null;const easeInCubic=t=>t*t*t;window.requestAnimationFrame(function step(timestamp){if(!start)start=timestamp;const progress=timestamp-start,percent=Math.min(progress/duration,1);window.scrollTo(0,startPosition+distance*easeInCubic(percent));if(progress<duration)window.requestAnimationFrame(step)})}})});const faders=document.querySelectorAll('.fade-in-section'),appearOptions={threshold:.15,rootMargin:"0px 0px -50px 0px"},appearOnScroll=new IntersectionObserver(function(entries,observer){entries.forEach(entry=>{if(!entry.isIntersecting){return}else{entry.target.classList.add('is-visible');observer.unobserve(entry.target)}})},appearOptions);faders.forEach(fader=>{appearOnScroll.observe(fader)});
